insert into public.sujets_examen_ecrit_baremes (exam_id, titre, duree_min, bareme_total, sections_meta)
values
  ('exam-bac2022-blanc-ecrit', 'Bac Blanc 2022 - Épreuve Écrite Systèmes & Technologies de l''Informatique', 180, 20, $json$[{"id":"ex1-qcm","title":"Exercice N° 1 : Concepts Web, PHP & SQL (2.5 pts)","type":"qcm","pointsMax":2.5,"questions":[{"id":"EX1-Q1","points":0.5,"multiple":false,"correctAnswers":["opt-num"],"explanation":"mysqli_num_rows($res) retourne le nombre de lignes d'un jeu de résultats SELECT."},{"id":"EX1-Q2","points":0.5,"multiple":false,"correctAnswers":["opt-false"],"explanation":"\"123\" est convertible en nombre, donc isNaN(\"123\") retourne false."},{"id":"EX1-Q3","points":0.5,"multiple":false,"correctAnswers":["opt-order-distinct"],"explanation":"ORDER BY trie les lignes et DISTINCT élimine les doublons."},{"id":"EX1-Q4","points":0.5,"multiple":false,"correctAnswers":["opt-onload"],"explanation":"L'événement onload sur <body> se déclenche à la fin du chargement du document."},{"id":"EX1-Q5","points":0.5,"multiple":false,"correctAnswers":["opt-cascade"],"explanation":"ON DELETE CASCADE propage la suppression de la table mère vers la table fille."}]},{"id":"ex2-php","title":"Exercice N° 2 : Tableaux associatifs PHP & HTML (3 pts)","type":"code_analysis","pointsMax":3,"questions":[{"id":"EX2-Q1","points":1,"type":"code_analysis","explanation":"Un tableau associatif PHP s'écrit array(\"Ali\" => 18, \"Sami\" => 22, \"Mouna\" => 25, \"Ines\" => 19)."},{"id":"EX2-Q2","points":1,"type":"code_analysis","explanation":"foreach ($ages as $nom => $age) parcourt les paires clé/valeur ; if ($age >= 20) filtre les personnes majeures >= 20 ans."},{"id":"EX2-Q3","points":1,"type":"code_analysis","explanation":"Seuls Sami (22) et Mouna (25) ont un âge supérieur ou égal à 20."}]},{"id":"ex3-contraintes","title":"Exercice N° 3 : Contraintes d'Intégrité SQL (3 pts)","type":"modeling","pointsMax":3,"questions":[{"id":"EX3-VF-1","points":0.5,"type":"text","explanation":"Faux : une table possède une seule clé primaire (qui peut toutefois être composée de plusieurs colonnes)."},{"id":"EX3-VF-2","points":0.5,"type":"text","explanation":"Vrai : sans contrainte NOT NULL, une clé étrangère accepte NULL."},{"id":"EX3-VF-3","points":0.5,"type":"text","explanation":"Faux : elle supprime les lignes dépendantes dans la table fille, jamais la table mère."},{"id":"EX3-CI-1","points":0.5,"type":"text","explanation":"CHECK (Salaire > 0) est une contrainte d'intégrité de domaine."},{"id":"EX3-CI-2","points":0.5,"type":"text","explanation":"La clé étrangère REFERENCES assure l'intégrité référentielle."},{"id":"EX3-CI-3","points":0.5,"type":"text","explanation":"La contrainte UNIQUE empêche les doublons sur une colonne."}]},{"id":"ex4-sql-vehicules","title":"Exercice N° 4 (Partie A) : Requêtes SQL - Annonces Véhicules (5.5 pts)","type":"sql","pointsMax":5.5,"questions":[{"id":"EX4-SQL-1","points":0.75,"type":"dml","explanation":"On applique * 0.9 aux annonces dont ImmatVeh appartient aux véhicules de PuisFisc >= 6."},{"id":"EX4-SQL-2","points":0.75,"type":"dml","explanation":"DELETE FROM ANNONCE WHERE DateAnn < '2020-01-01' (ou YEAR(DateAnn) < 2020 en MySQL)."},{"id":"EX4-SQL-3","points":1,"type":"query","explanation":"Jointure MODELE-VEHICULE-ANNONCE avec DISTINCT sur NomMod."},{"id":"EX4-SQL-4","points":1,"type":"query","explanation":"GROUP BY IdMod avec COUNT(*)."},{"id":"EX4-SQL-5","points":1,"type":"query","explanation":"Jointure CONSTRUCTEUR-MODELE-VEHICULE filtrée sur PuisFisc = 6."},{"id":"EX4-SQL-6","points":1,"type":"query","explanation":"Regroupement sur IdVend avec SUM(PrixVente)."}]},{"id":"ex4-web","title":"Exercice N° 4 (Partie B) : Formulaire HTML, JS & PHP (3 pts)","type":"code_analysis","pointsMax":3,"questions":[{"id":"EX4-WEB-1","points":1,"type":"code_analysis","explanation":"action=\"constructeur.php\" method=\"POST\" onsubmit=\"return Verif()\"."},{"id":"EX4-WEB-2","points":1,"type":"code_analysis","explanation":"On vérifie idc.trim() === \"\" || isNaN(idc) et on retourne false."},{"id":"EX4-WEB-3","points":1,"type":"code_analysis","explanation":"Récupération via $_POST['idc'] puis requête SELECT filtrée sur IdConst."}]},{"id":"ex5-associations","title":"Exercice N° 5 : Associations & LDD SQL (3 pts)","type":"modeling","pointsMax":3,"questions":[{"id":"EX5-Q1","points":1,"type":"representation","explanation":"PARTICIPE(#NumAdh, #CodeActiv, DateInsc)."},{"id":"EX5-Q2","points":1,"type":"ddl","explanation":"CREATE TABLE ASSOCIATION (CodeAssoc VARCHAR(10) PRIMARY KEY, NomAssoc VARCHAR(50) NOT NULL, Ville VARCHAR(30));"},{"id":"EX5-Q3","points":1,"type":"ddl","explanation":"ALTER TABLE ACTIVITE MODIFY NomActiv VARCHAR(50) NOT NULL;"}]}]$json$::jsonb),
  ('exam-bac2023-blanc-ecrit', 'Bac Blanc 2023 - Épreuve Écrite Systèmes & Technologies de l''Informatique', 180, 20, $json$[{"id":"ex1-qcm","title":"Exercice N° 1 : Validation de concepts Web & SQL (3 pts)","type":"qcm","pointsMax":3,"questions":[{"id":"EX1-Q1","points":0.5,"multiple":false,"correctAnswers":["opt-ok"],"explanation":"79 est le code ASCII de 'O' et 75 celui de 'K'."},{"id":"EX1-Q2","points":0.5,"multiple":false,"correctAnswers":["opt-false-num"],"explanation":"isNaN(\"123\") vaut false car la chaîne est convertible en nombre."},{"id":"EX1-Q3","points":0.5,"multiple":false,"correctAnswers":["opt-alter"],"explanation":"ALTER TABLE est une instruction LDD de modification de structure, pas une clause de SELECT."},{"id":"EX1-Q4","points":0.5,"multiple":false,"correctAnswers":["opt-join"],"explanation":"La jointure combine des enregistrements de plusieurs tables selon une condition de lien."},{"id":"EX1-Q5","points":0.5,"multiple":false,"correctAnswers":["opt-cascade"],"explanation":"ON UPDATE CASCADE propage les modifications de clé primaire vers les clés étrangères dépendantes."},{"id":"EX1-Q6","points":0.5,"multiple":false,"correctAnswers":["opt-valid"],"explanation":"checkdate() retourne true si la date grégorienne est valide."}]},{"id":"ex2-transfert","title":"Exercice N° 2 : Base Gestion_Transfert & LDD SQL (5 pts)","type":"modeling","pointsMax":5,"questions":[{"id":"EX2-Q1","points":1,"type":"representation","explanation":"Service(#NumService, NomService) ; Employe(#Matricule, Nomprenom, Taille_Max, NumService#) ; Transfert(#NumTransfert, DateHeureTransfert, Duree, TailleDonnees, Matricule#)."},{"id":"EX2-VF","points":1,"type":"text","explanation":"Réponse officielle : F, V, V, F."},{"id":"EX2-Q3","points":1,"type":"ddl","explanation":"ALTER TABLE Transfert ADD CONSTRAINT chk_duree CHECK (Duree > 0);"},{"id":"EX2-Q4","points":1,"type":"text","explanation":"Il faut recréer ou modifier la clé étrangère avec ON DELETE CASCADE."},{"id":"EX2-Q5","points"