  ('exam-bac2024-blanc-ecrit', 'Bac Blanc 2024 - Épreuve Écrite Systèmes & Technologies de l''Informatique', 180, 20, $json$[{"id":"ex1-qcm","title":"Exercice N° 1 (Partie 1) : QCM HTML5, CSS, JS, PHP & SQL (2.5 pts)","type":"qcm","pointsMax":2.5,"questions":[{"id":"EX1-Q1","points":0.5,"multiple":false,"correctAnswers":["opt-onblur"],"explanation":"onblur se déclenche à la perte de focus."},{"id":"EX1-Q2","points":0.5,"multiple":false,"correctAnswers":["opt-transform"],"explanation":"La propriété CSS standard est transform: translate(100px);."},{"id":"EX1-Q3","points":0.5,"multiple":false,"correctAnswers":["opt-setmonth"],"explanation":"setMonth() modifie le mois d'un objet Date."},{"id":"EX1-Q4","points":0.5,"multiple":false,"correctAnswers":["opt-null"],"explanation":"isset($a) retourne false si $a n'est pas définie ou vaut NULL."},{"id":"EX1-Q5","points":0.5,"multiple":false,"correctAnswers":["opt-table"],"explanation":"UNIQUE garantit l'unicité entre lignes d'une même table."}]},{"id":"ex1-assoc","title":"Exercice N° 1 (Parties 2 & 3) : Fonctions & Propriétés CSS (1.25 pt)","type":"code_analysis","pointsMax":1.25,"questions":[{"id":"EX1-FCT","points":0.75,"type":"code_analysis","explanation":"1: isNaN(), 2: checkdate(), 3: Now(), 4: parseInt(), 5: date()."},{"id":"EX1-CSS","points":0.5,"type":"code_analysis","explanation":"text-align: center; position: absolute; filter: invert(); display: inline-block; transform: rotate(90deg);"}]},{"id":"ex2-client","title":"Exercice N° 2 : Formulaire BD_Gestion (HTML, JS & PHP) (3.25 pts)","type":"code_analysis","pointsMax":3.25,"questions":[{"id":"EX2-HTML","points":1.25,"type":"code_analysis","explanation":"action=\"ajoutClient.php\", method=\"POST\", onsubmit=\"return Verif()\", submit, reset."},{"id":"EX2-JS","points":1,"type":"code_analysis","explanation":"mat.length, mat.substr(0, 2), nmpr.trim(), nmpr2.indexOf(\" \")."},{"id":"EX2-PHP","points":1,"type":"code_analysis","explanation":"strpos($nompre, \" \"), substr($nompre, 0, $p), strtoupper($nom), str_replace($nom, $nommajus, $nompre)."}]},{"id":"ex3-streaming-ddl","title":"Exercice N° 3 (Parties 1 & 2-II) : Streaming_HD — Cardinalités & LDD (3.5 pts)","type":"modeling","pointsMax":3.5,"questions":[{"id":"EX3-VF","points":1,"type":"text","explanation":"Réponse officielle : Faux, Vrai, Vrai, Faux."},{"id":"EX3-DDL-1","points":0.5,"type":"ddl","explanation":"ALTER TABLE Streamer MODIFY Pseudo VARCHAR(50);"},{"id":"EX3-DDL-2","points":0.5,"type":"ddl","explanation":"ALTER TABLE TypeContenu ADD Categorie VARCHAR(20) NOT NULL;"},{"id":"EX3-DDL-3","points":0.5,"type":"ddl","explanation":"ALTER TABLE Contenu ADD CONSTRAINT c1 CHECK (Duree BETWEEN 1 AND 60);"},{"id":"EX3-DDL-4","points":0.5,"type":"ddl","explanation":"CREATE TABLE Adresse (CodeMail VARCHAR(10) PRIMARY KEY, Email VARCHAR(40) NOT NULL UNIQUE, IdStream INT REFERENCES Streamer(IdStream));"},{"id":"EX3-DDL-5","points":0.5,"type":"ddl","explanation":"ALTER TABLE Streamer DROP COLUMN Email;"}]},{"id":"ex3-streaming-sql","title":"Exercice N° 3 (Partie 2-III) : Requêtes SQL Streaming_HD (6 pts)","type":"sql","pointsMax":6,"questions":[{"id":"EX3-SQL-1","points":1,"type":"dml","explanation":"UPDATE Contenu SET Mode = 'D' WHERE IdChaine = 'C005';"},{"id":"EX3-SQL-2","points":1,"type":"dml","explanation":"DELETE FROM Contenu WHERE DateCreation < '2017-01-01';"},{"id":"EX3-SQL-3","points":1,"type":"query","explanation":"Jointure Contenu-TypeContenu filtrée sur NbreVues > 1000."},{"id":"EX3-SQL-4","points":1,"type":"query","explanation":"Filtre sur l'année 2024 et ORDER BY NbreVues DESC."},{"id":"EX3-SQL-5","points":1,"type":"query","explanation":"Jointure Chaine-Contenu-TypeContenu avec NomType = 'Education'."},{"id":"EX3-SQL-6","points":1,"type":"query","explanation":"GROUP BY IdChaine avec AVG(Duree)."}]},{"id":"ex4-maintenance","title":"Exercice N° 4 : Conception & Normalisation Maintenance (3.5 pts)","type":"modeling","pointsMax":3.5,"questions":[{"id":"EX4-Q1","points":1,"type"